-- The documentation project of the site, written as a wiki: a clickable contents at the top, one section per topic, and every setting listed.
-- Paste into Supabase > SQL Editor > Run. Safe to run again: it replaces the project with url_title 'website-documentation'.
-- To remove it later:  delete from public.projects where url_title = 'website-documentation';

delete from public.projects where url_title = 'website-documentation';

insert into public.projects (id, title, url_title, description, status, content, last_update, created_at) values
(
    gen_random_uuid(),
    'Website documentation',
    'website-documentation',
    'The documentation of this site: how the music visualizer listens to sound and finds the beat, what every effect does, every page and every setting. Use the contents to jump around.',
    'active',
    $j$[{"type": "embed", "value": "<div style='display:flex;flex-wrap:wrap;gap:20px;align-items:start'><div style='flex:1 1 300px;min-width:0'><h2 style='margin-top:0'>XMega.com</h2><p>This is the documentation of my personal site: how it works, what every page does and how the music visualizer listens to sound and decides what to show. It is written like a wiki: use the contents below, and the <b>&uarr; contents</b> link at the end of every section, to jump around.</p><p>The site has no commercial use. It exists to show how my skills grow, and it is also a page of my portfolio.</p></div><div style='flex:1 1 300px;min-width:0'><div style='border:2px solid #0e7490;background:#083344;padding:12px'><h3 style='text-align:center;margin-bottom:8px'>At a glance</h3><table><tr><th>Stack</th><td>React 19, Vite 7, Tailwind CSS 4, React Router 7</td></tr><tr><th>Backend</th><td>Supabase (accounts, database, file storage)</td></tr><tr><th>Music</th><td>YouTube, SoundCloud, Spotify links, uploaded files</td></tr><tr><th>Beat</th><td>Plain signal processing, no AI, no audio libraries</td></tr><tr><th>Pages</th><td>Home, music, projects, blog, gallery, skill tracker, mural, settings, feedback, about</td></tr><tr><th>Made by</th><td>Mega</td></tr></table></div></div></div>"}, {"type": "embed", "value": "<h2 id='doc-contents' style='scroll-margin-top:8px'>Contents</h2><div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px'><div style='border:2px solid #0e7490;background:#083344;padding:10px 14px'><b>1. The site</b><ul style='margin-top:6px'><li><a href='#doc-overview'>What the site is</a></li><li><a href='#doc-architecture'>How the pieces fit</a></li></ul></div><div style='border:2px solid #0e7490;background:#083344;padding:10px 14px'><b>2. The visualizer</b><ul style='margin-top:6px'><li><a href='#doc-clock'>The beat clock</a></li><li><a href='#doc-listening'>Listening to the sound</a></li><li><a href='#doc-bands'>The 24 bands</a></li><li><a href='#doc-tempo'>Finding the tempo</a></li><li><a href='#doc-hits'>Finding the hits</a></li><li><a href='#doc-groove'>The groove: grid and patterns</a></li><li><a href='#doc-manual'>Tap, type, pad and the phone fallback</a></li><li><a href='#doc-effects'>The effects</a></li><li><a href='#doc-drops'>Breaks, build-ups and drops</a></li><li><a href='#doc-openspace'>The open space</a></li><li><a href='#doc-displays'>Bars, rings and the rest of the site</a></li><li><a href='#doc-tools'>Tools: data panel, settings panel, pad</a></li><li><a href='#doc-perf'>Performance and presets</a></li><li><a href='#doc-settings'>Every setting</a></li></ul></div><div style='border:2px solid #0e7490;background:#083344;padding:10px 14px'><b>3. The rest of the site</b><ul style='margin-top:6px'><li><a href='#doc-music'>Music player and /music</a></li><li><a href='#doc-accounts'>Accounts and profiles</a></li><li><a href='#doc-chat'>Live chat</a></li><li><a href='#doc-mural'>Mural</a></li><li><a href='#doc-skills'>Skill tracker</a></li><li><a href='#doc-content'>Projects, blog and gallery</a></li><li><a href='#doc-backend'>Backend and storage</a></li></ul></div><div style='border:2px solid #0e7490;background:#083344;padding:10px 14px'><b>4. Reference</b><ul style='margin-top:6px'><li><a href='#doc-limits'>Known limits</a></li><li><a href='#doc-controls'>Keys, links and URL tricks</a></li><li><a href='#doc-glossary'>Glossary</a></li></ul></div></div>"}, {"type": "text", "value": "<h2 id='doc-overview' style='scroll-margin-top:8px'>What the site is</h2><p>XMega.com is a personal site built around one idea: <b>the page listens to music</b>. Press play on any song, or let the site hear the sound of the browser tab, and the logo, the wall of images, the lasers, the header, the edges of the screen and even the small bars in the player move to the beat.</p><p>Around that core there is the rest of what a personal site needs: a music page with my own tracks, a blog, a gallery, a project page (this one), a public skill tracker where visitors can follow how I improve and track their own progress too, a live chat on the home page and a guestbook (the mural).</p><p>Everything is made by hand: the design, the code, the database and the sound analysis. The visualizer in particular is plain signal processing, written from scratch: no machine learning and no audio libraries.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-architecture' style='scroll-margin-top:8px'>How the pieces fit</h2><p>Sound goes in on the left. A separate thread analyses it. One shared <b>beat clock</b> hands out the tempo to every animation, and a small event bus tells the effects when a drum was hit.</p><h3>On a computer, following the tab's sound</h3>"}, {"type": "embed", "value": "<div style='display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0'><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Player (YouTube, SoundCloud, file)</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Browser shares the tab's sound</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Worker thread: bands, tempo, hits</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Groove: puts hits on the grid</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Beat clock + event bus</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Effects, bars, logo, header</div></div>"}, {"type": "text", "value": "<h3>On a phone, or with nothing shared</h3>"}, {"type": "embed", "value": "<div style='display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0'><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Tempo: default 144, tapped or typed</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Beat clock</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Pretend drums (kick, snare, hat on the beat)</div><span style='color:#22d3ee'>&rarr;</span><div style='border:2px solid #0e7490;background:#083344;padding:6px 10px;font-size:14px;text-align:center'>Same effects and bars</div></div>"}, {"type": "text", "value": "<p>Both paths end in the same place, so every effect works with real hits or with made-up ones. The three pieces to remember:</p><ul><li><b>The clock</b> (<code>music/BeatProvider.jsx</code>): one tempo and one beat position for the whole site.</li><li><b>The listener</b> (<code>music/beat-worker.js</code>, <code>tempo.js</code>, <code>hits.js</code>, <code>groove.js</code>): turns sound into bands, tempo and hits.</li><li><b>The effects</b> (<code>components/reactions-layer.jsx</code>, <code>logo-bars.jsx</code>, <code>site-beat.jsx</code>...): turn hits into things you can see.</li></ul><p>All of them are tuned from <b>one list of numbers</b> (<code>music/settings.js</code>, 89 settings), which is also what draws the settings panel. See <a href='#doc-settings'>Every setting</a>.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-clock' style='scroll-margin-top:8px'>The beat clock</h2><p>The site keeps <b>one clock</b>: a tempo in beats per minute and the moment a beat started (the <i>anchor</i>). Everything that moves in time asks that clock, so a pulsing logo and a blinking edge never drift apart. Most pulses are plain CSS animations that read two variables set on the page, <code>--beat</code> (how long a beat lasts) and <code>--beat-peak</code> (how big the pulse is). The clock only sets those two and keeps every animation on the right phase, also on pages that open later.</p><p>The clock has four modes:</p><div style='overflow-x:auto'><table><tr><th>Mode</th><th>Where the tempo comes from</th><th>When</th></tr><tr><td><b>idle</b></td><td>A default of 144 BPM, a soft pulse not tied to any music</td><td>Nothing is playing or set</td></tr><tr><td><b>analyzing</b></td><td>The tab's sound is being listened to but no tempo is known yet: the pulse is held still</td><td>Right after a song starts, until the first reading</td></tr><tr><td><b>auto</b></td><td>The tempo <i>and</i> the beat positions come from the tab's sound</td><td>Computer, Chrome or Edge, sound shared</td></tr><tr><td><b>manual</b></td><td>The visitor tapped it or typed a BPM</td><td>Any device</td></tr></table></div><p>Moving between modes is gentle: when a new song starts, the old tempo keeps pulsing until the new one is found, and the pulse is only held still when leaving idle or manual for a first reading.</p><h3>Latency and nudging</h3><p>Sound takes time to get from the page to your ears, and the analysis takes time to notice a hit. The clock subtracts the audio output latency and a measured detection delay (27 ms by default). For the rest there is a fine nudge: the keys <code>[</code> and <code>]</code> move the pulse 10 ms earlier or later.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-listening' style='scroll-margin-top:8px'>Listening to the sound</h2><p>A web page cannot hear the speakers. The trick used here: the browser's own <b>share this tab's sound</b> option. When the first song starts, the click that started it is the permission to ask, the browser shows its share dialog, and from then on the tab's audio stream is read for as long as the visitor stays on the site. Later songs only restart the analysis, they do not ask again.</p><ul><li>The stream is read by a <b>worker thread</b> (<code>beat-worker.js</code>), so the analysis never slows the page down.</li><li>It needs a desktop Chromium browser (Chrome, Edge). <b>Phones cannot share a tab's sound</b>, so there the site uses the pretend drums instead (see <a href='#doc-manual'>Tap, type, pad and the phone fallback</a>).</li><li>While the site follows the tab's sound, the \"auto\" button in the player is lit; the small \"x\" lets go of everything and goes back to the idle 144 BPM.</li></ul><h3>Lag mode (test mode)</h3><p>An experimental option: the browser silences the tab, and the site plays the sound back itself, <b>4 seconds late</b>. That gives the analysis time to find the beat <i>before</i> it is heard, so the effects can land exactly on the hit instead of just after it. It is a test mode: it is not remembered between visits, and turning it on or off means the share has to be asked for again (the browser fixes \"silence the tab\" when the share starts).</p><h3>Feedback sounds and the echo guard</h3><p>For tuning there are optional sounds that play whenever the site finds a hit (a thump for kicks, a clap for snares, a tick for hats, softer for hits filled in from a pattern), like the hit sounds in osu!. Since the site listens to this very tab, it would hear them as drum hits. So every sound it plays is remembered, and a hit found right after one (of a kind that sound could wake up) is thrown away. The counter in the data panel shows how many were thrown away.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-bands' style='scroll-margin-top:8px'>The 24 bands</h2><p>Each slice of audio (an FFT of 2048 samples, moving 512 samples at a time, about <b>94 readings per second</b> at 48 kHz) is turned into <b>24 frequency bands</b>, spaced like pitch is heard (logarithmically) between 40 Hz and 10 kHz. Those 24 numbers are what the bars in the player, the ring around the logo and the header all draw.</p><p>The loudness of each band is scaled by what it has recently peaked at (the memory halves in about 8 seconds), so quiet and loud songs look alike. The 24 bars share one scale, so their shape is the real shape of the sound. They are sent to the page about 30 times a second.</p><h3>The five groups</h3><p>For decisions, the bands are grouped in five parts. The first and last borders can be moved in the settings.</p><div style='overflow-x:auto'><table><tr><th>Group</th><th>Range (default)</th><th>What lives there</th></tr><tr><td><b>low</b></td><td>up to 160 Hz</td><td>Kick drums, sub bass</td></tr><tr><td><b>body</b></td><td>160 to 450 Hz</td><td>The thump of a snare, the body of instruments</td></tr><tr><td><b>mid</b></td><td>450 Hz to 1 kHz</td><td>Snare and voices</td></tr><tr><td><b>crack</b></td><td>1 kHz to 5 kHz</td><td>The snap of a snare, the attack of hats</td></tr><tr><td><b>air</b></td><td>above 5 kHz</td><td>Hi-hats and shine</td></tr></table></div><p>The page also gets a rough <b>tone</b>: where the weight of the sound sits above the kick range, from low to high. The big laser uses it (see <a href='#doc-effects'>The effects</a>).</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-tempo' style='scroll-margin-top:8px'>Finding the tempo</h2><p>The tempo comes from <b>onset strength</b>: for every reading, how much new sound started, computed as the growth of each band compared with the previous reading (<i>spectral flux</i>), compressed with a logarithm. A beat shows up as a regular rhythm in that signal.</p><ol><li><b>Clean up:</b> the slow-moving part is removed so only the hits stay.</li><li><b>Autocorrelation:</b> the signal is compared with itself at every delay that matches a tempo (from half the lowest to twice the highest BPM, to check octaves).</li><li><b>Score each tempo</b> in range by its own peak plus its multiples (a real tempo repeats at 2x, 3x...), with a gentle preference for tempos people actually use, around 120 BPM.</li><li><b>Half or double?</b> When the same pattern also fits at twice the tempo, the faster one wins: pulsing on every half-beat lands on the beats <i>and</i> the off-beats, while a half-speed pulse would miss the off-beats.</li><li><b>Fine tuning:</b> the best beat grid within 2% of the winner.</li></ol><h3>A flywheel, not a jumpy needle</h3><p>A new tempo is only accepted after it shows up in several estimates in a row, so a break, a fill or a syncopated bar does not make the beat jump. When the tempo stays the same, the beat grid keeps turning like a flywheel: the tempo moves slowly toward the new estimate; a small phase disagreement is followed a little, a big one is ignored unless the same disagreement shows up estimate after estimate (the music really moved). The same pattern read at another speed (octave flips, 3:2 or 4:3 readings from syncopation) is not treated as a new tempo.</p><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Meaning</th></tr><tr><td>lowest BPM</td><td>70</td><td>The slowest tempo it will pick</td></tr><tr><td>highest BPM</td><td>190</td><td>The fastest tempo it will pick</td></tr><tr><td>prefer faster</td><td>0.6</td><td>How much to favour the faster of two fitting tempos</td></tr><tr><td>usual BPM</td><td>120</td><td>The tempo it expects first</td></tr></table></div><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-hits' style='scroll-margin-top:8px'>Finding the hits</h2><p>The hit detector looks at how much each group grew since the last reading, and compares it with <b>its own recent level</b> (a running average and spread, so quiet and loud tracks work alike). A rise counts only when it is <b>3.2 spreads above</b> that level, and never when it is smaller than a fixed floor, so silence and hiss are not hits. Then the <b>shape</b> of the rise decides what it was:</p><div style='overflow-x:auto'><table><tr><th>Hit</th><th>A sudden rise in...</th><th>The shape that makes it that</th><th>Floor</th></tr><tr><td><b>Kick</b></td><td>the low end (40 to 160 Hz)</td><td>Low is at least 0.7 times body (a snare's thump lives in the body range)</td><td>0.35</td></tr><tr><td><b>Snare</b></td><td>the mids and the snap (450 Hz to 5 kHz)</td><td>Snap is at least 0.25 times low (a kick alone has almost no snap); the low end is left out of its level because a kick's pitch sweep also fills 150 to 450 Hz</td><td>0.9</td></tr><tr><td><b>Hat</b></td><td>the air and the snap</td><td>Air plus snap is at least 1.5 times everything below</td><td>0.5</td></tr></table></div><p>After a kick or snare the detector waits 70 ms before hearing another, and 40 ms after a hat. A hit is reported one reading after it happens, because the detector waits for the peak. Each hit carries a strength from about 1 (a normal hit) to 4.</p><p>Every number above is a setting (<a href='#doc-settings'>group: detection</a>), and the sensitivity of each channel can be set to 0 to turn it off.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-groove' style='scroll-margin-top:8px'>The groove: grid and patterns</h2><p>The detector hears things; the <b>groove</b> (<code>music/groove.js</code>) decides which of them count, so the reactions stay in time and one noisy moment does not break the show.</p><ul><li><b>Snap to the grid.</b> Every hit is moved to the nearest 16th note of the beat clock (a bar has 16 steps). One step can fire only once per kind, so one kick heard five times is one kick.</li><li><b>Off-grid hits are dropped.</b> A hit more than 0.3 of a step away from the grid is dropped, unless it is strong.</li><li><b>Memory of the bar.</b> For each kind the groove remembers how often each of the 16 steps had a hit lately.</li><li><b>Ghosts.</b> Once a pattern is known, a step that always has a hit but was missed is filled in (a <i>ghost</i> hit), and a weak hit on a step that never has one is dropped. One tiny change does not break a pattern that was going well.</li><li><b>Swing.</b> 50% is straight 16ths; 66.7% gives a triplet feel (shuffle, trap, hip hop).</li><li><b>The grid follows by ear.</b> The grid itself slowly shifts to where kicks and snares really land.</li></ul><h3>Known kick patterns</h3><p>Some kick patterns show up again and again. When what was heard fits one of them well for 2 bars in a row, it becomes the song's default: missing kicks on its steps are filled in and weak odd hits are dropped. It is let go after 2 bars that do not fit, or when the sound stops. Another pattern must fit 0.25 better to take over.</p><div style='overflow-x:auto'><table><tr><th>Pattern</th><th>Steps with a kick (of 16)</th><th>Typical music</th></tr><tr><td>four on the floor</td><td>0, 4, 8, 12</td><td>House, techno, disco, most dance music</td></tr><tr><td>two-step</td><td>0, 10</td><td>Drum &amp; bass, breakbeat</td></tr><tr><td>breaks</td><td>0, 6, 10</td><td>Hip hop, boom bap, trap-ish</td></tr><tr><td>half-time</td><td>0</td><td>Dubstep, slow trap</td></tr><tr><td>eighths</td><td>0, 2, 4, 6, 8, 10, 12, 14</td><td>A build-up before a drop</td></tr><tr><td>sixteenths</td><td>all 16</td><td>The roll right before a drop</td></tr></table></div><h3>Forced four on the floor</h3><p>When the sound is <b>loud and messy</b>, the site gives up on the hits and puts a kick on every beat. Messy means one of: hits thrown away 1.5 times more than passed, 2 tempo changes in 10 seconds, or no kick for 6 beats after a kick pattern was going. It switches on after 2 seconds of that and off after 4 seconds without it. Settings: <a href='#doc-settings'>group: forced four on the floor</a>.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-manual' style='scroll-margin-top:8px'>Tap, type, pad and the phone fallback</h2><p>When the site cannot hear the sound, the visitor (or the phone) gives it the tempo.</p><h3>Tap</h3><p>The <b>tap</b> button, or the <code>T</code> key, counts from the second tap: the gap between the last two taps is the tempo and the last tap is a beat. On a touch screen, tapping an empty part of the page does the same. Until a tempo is set, a hint under the logo says to tap, and afterwards the tempo itself shows there, faint, so it can always be seen. Tapping is not used while the tab's sound is followed or a BPM was typed.</p><h3>Type</h3><p>A BPM typed in the player starts at the moment of the Enter. A later tap only moves where the beat falls, not the tempo.</p><h3>The pad</h3><p>The pad (kick, snare and hat buttons) does more than play what is tapped: it listens to the rhythm played, finds the tempo (4 hits or more, between 70 and 190 BPM), and keeps going with the pattern (at most one bar, 16 steps) exactly where the player left off. More hits can be added on top while it plays. A pause of 2.5 seconds starts a new phrase. The tempo found goes to the beat clock, so the whole site pulses with it.</p><h3>Pretend drums</h3><p>Where there are no real bands (phones, or nothing shared) the bars and the logo ring still move, with a pattern made only from the tempo (<code>music/fake-bands.js</code>):</p><ul><li><b>Kick</b> on every beat: a tall wave that runs from the lowest band to the highest in about two and a half steps and gets smaller as it goes.</li><li><b>Snare</b> on beats 2 and 4: a strong swell in the middle bands.</li><li><b>Hat</b> between the kicks, a lighter swell in the high bands. Every 8 bars it switches between \"only between the kicks\" and \"between and on the kicks\".</li></ul><p>To avoid looking mechanical, every hit gets its own made-up numbers (how hard it is, which side of the spectrum leans louder). They are the same for the whole hit, so nothing flickers. Real heard sound always wins over the pretend pattern.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-effects' style='scroll-margin-top:8px'>The effects</h2><p>Each kind of hit has its own family of <b>looks</b>. A new look is picked at random every <b>16 beats</b> (never the same twice in a row), so the page keeps changing without a script. Now and then a second look is added on top (30% of the time by default; always for the colour-only looks), and two looks never change the same property of the images. A look that would flash is skipped when the flash limit is reached (3 per second by default, the usual safe limit for people sensitive to flashing).</p><h3>Kick looks</h3><div style='overflow-x:auto'><table><tr><th>Look</th><th>What it does</th></tr><tr><td>checker</td><td>Chessboard: half of the images grow while the other half shrink, and they swap on the next kick</td></tr><tr><td>shove</td><td>Columns as pistons: the odd columns jump forward along the diagonal while the even ones fall back, then swap</td></tr><tr><td>flash</td><td>The whole wall punches out and flashes, then settles</td></tr><tr><td>lines</td><td>One line leaves each side and drifts inward, thick at first and thinning out until it is gone, like the logo's ring</td></tr><tr><td>slide</td><td>The whole grid steps one column toward the bottom right on every kick; what leaves comes back at the top left, so it looks like an endless grid</td></tr><tr><td>lanes</td><td>Alternate columns light up and the others dim, swapping on every kick</td></tr></table></div><h3>Snare looks</h3><div style='overflow-x:auto'><table><tr><th>Look</th><th>What it does</th></tr><tr><td>laser</td><td>A bright line sweeps across at a random height and angle, from alternating sides. It also fires on most snares whatever the look is (60% by default)</td></tr><tr><td>columns</td><td>Like the chessboard, but whole columns: the even ones grow while the odd ones shrink, then swap</td></tr><tr><td>glitch</td><td>The title splits into two colours and tilts for a moment</td></tr><tr><td>hue</td><td>The colours of the wall spin for a moment</td></tr><tr><td>pixels</td><td>Little squares burst out of the logo</td></tr></table></div><h3>Hat looks</h3><p>Small ones, because hats come often.</p><div style='overflow-x:auto'><table><tr><th>Look</th><th>What it does</th></tr><tr><td>twinkle</td><td>One image lights up and fades</td></tr><tr><td>sparks</td><td>A few specks light up where they are and go out</td></tr><tr><td>tick</td><td>A short thin tick of light at a random height, a small cousin of the laser</td></tr><tr><td>blink</td><td>The title blinks white for a moment</td></tr></table></div><h3>Effects that follow the loudness all the time</h3><ul><li><b>Logo pulse:</b> the logo and the title hit on every beat; very quiet music makes the pulse weaker, and the size of the logo follows how loud it is.</li><li><b>Pixels:</b> little squares stream out of the logo and rise from the floor, as many as the sound is loud.</li><li><b>Thin lasers:</b> six beams fan out from the bottom corners behind the images and sweep with the music.</li><li><b>Big laser:</b> rare, wide, from the middle of the logo (above the images, below the logo). It appears for a few seconds when the sound has been holding, waits 12 to 26 seconds between appearances and stays while the sound that brought it is still strong (up to 90 seconds). When the tone of the music changes it starts turning, speeding up and slowing down at a constant rate so the turn is smooth. It is never wider than 95% of the logo's diameter. Thin bright <b>streaks</b> run along it away from the logo, as if it were really firing.</li><li><b>Mood colour:</b> slow averages of how fast, how bright and how loud the music is become a faint glow: calm and dark is blue, fast, bright and loud is red. Only a rough guess.</li><li><b>Wall speed:</b> the images move faster while the sound is loud (only for real, followed sound).</li><li><b>Title swap:</b> every so often the title swaps its colours on a run of snares (4, 8, 12 or 16, one swap per snare), so it ends back to normal: cyan letters with a black edge or black letters with a cyan edge.</li></ul><p>Without followed sound, the hits are made up from the beat clock: a kick on every beat and a snare on every other one. The strength of each kind, how often the big moves happen and which parts of the page may react (logo, wall, title, pixels) are all settings.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-drops' style='scroll-margin-top:8px'>Breaks, build-ups and drops</h2><p>The site also reacts to the <b>shape of the song</b>, not only to single hits.</p><div style='overflow-x:auto'><table><tr><th>Event</th><th>How it is recognised</th><th>What the site does</th></tr><tr><td><b>Break</b></td><td>The sound has been much quieter for a moment (1.2 s) after being loud</td><td>The wall dims, the pulse of the logo gets smaller and the effects calm down</td></tr><tr><td><b>Build-up</b></td><td>A rise that is close to a straight line for 5 seconds or more (a riser)</td><td>Arms the drop: a jump up right after a build-up counts as a drop</td></tr><tr><td><b>Drop</b></td><td>The sound comes back loud all at once, right after a break or the end of a build-up. The jump needed is 0.25 divided by the drop sensitivity; at least 8 seconds apart by default</td><td>A flash, shock rings, a burst of pixels, the big laser, a fast grid and a glitch. Stars stream past around the page and the frame flashes cyan. A drop also opens the <a href='#doc-openspace'>open space</a></td></tr></table></div><p>A kick on its own proves nothing: kicks are also used in build-ups, so only the loudness over time decides. The sensitivity of each event and the cooldown are settings (<a href='#doc-settings'>group: song events</a>); 0 turns an event off.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-openspace' style='scroll-margin-top:8px'>The open space</h2><p>The most dramatic thing the site does. In a drop the images of the wall <b>shrink to half size and move far apart</b> and drift faster, for a few bars, leaving room around the logo. The page itself never changes size: only the wall images and the logo scale inside it (the whole page used to zoom out, and it was too heavy, so that was removed).</p><ul><li><b>Duration:</b> between 8 and 16 bars (4 beats each) after the drop; each drop picks a number between the two.</li><li><b>Transitions:</b> a straight line in time (0.8 s to shrink, 3 s to come back), so it never wobbles. There are only two states, normal and open.</li><li><b>Spacing:</b> because smaller images alone would leave the same density, half of them (a chessboard pattern) fade out while it is open, so the ones left are twice as far apart. A second set of images, hidden at rest, can fade in between them to fill the gaps; by default it stays off.</li><li><b>Speed:</b> the images move 2.5 times faster while it is open.</li><li><b>Busy music:</b> optionally it also opens when the big laser has stayed up for a while (off by default).</li><li><b>To see it without a drop:</b> the setting \"open space: hold now\" keeps it on.</li></ul><p>Settings: <a href='#doc-settings'>group: song events</a>, the ones starting with \"open space\".</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-displays' style='scroll-margin-top:8px'>Bars, rings and the rest of the site</h2><p>The same 24 bands (or the pretend drums) are drawn in several places:</p><div style='overflow-x:auto'><table><tr><th>Where</th><th>What it looks like</th></tr><tr><td><b>Home, around the logo</b></td><td>A ring of flat cyan bars, from the lowest band round to the highest and back (so it is not symmetric), with thinner dark-blue sub-bars between them as tall as the average of their neighbours, and a short uneven rim underneath so the bars look attached to the pixel-art logo. They start inside the logo's edge and follow its size right now, since it swells on every beat</td></tr><tr><td><b>Player</b></td><td>Bars behind the controls. Without sound a slow wave runs at the site's tempo</td></tr><tr><td><b>Header</b></td><td>The frequencies as symmetric bars, up and down from a middle line, with the name of what is playing floating over them (only the bars on narrow screens). Click to open the player</td></tr><tr><td><b>Music page</b></td><td>A long thin row of bars on each track</td></tr><tr><td><b>Every page</b></td><td>Kept quiet: a faint glow that breathes at the edge of the screen, a row of pixels along the bottom, a bar on each side and the header logo pulsing. All of it is CSS on the one site clock, so it costs almost nothing, and it only shows while a tempo is set</td></tr></table></div><p>The bars follow the sound without smoothing or cutting weak bands: a hit lands at once and only the fall is eased over about 60 ms, just to take away the feeling of lag.</p><p>The wall of images itself: every image travels along a diagonal path from the bottom left to the top right, in parallel columns that move at their own speeds. Columns are just wider apart than the images, so they almost touch but never overlap. Sizes follow the screen, so it looks right from a phone to a 4K monitor.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-tools' style='scroll-margin-top:8px'>Tools: data panel, settings panel, pad</h2><p>On the home page a very faint <b>gear</b> in the top left opens a small menu that turns on the visualizer's tools:</p><ul><li><b>Data panel:</b> what the site hears. One vertical bar per frequency band (labelled by group), the groove's recent decisions and the feedback sounds. A button copies the last few beats as text (what each kind did on its 16th steps and how loud each part of the sound was), so a problem can be read or sent later.</li><li><b>Settings panel:</b> every number the visualizer can be tuned with, drawn from the one list in <code>music/settings.js</code>. Values are saved in the browser, can be copied as text and pasted back in, and a value outside its limits is pulled back to the limit, so no typed number can break the page.</li><li><b>Pad:</b> opened from the \"pad\" button in the player. One button per effect (kick, snare, hat, a thin laser, a drop, and the big laser on or off with its strength) to fire the effects by hand. Kick, snare and hat go through the normal path, so they behave exactly like heard hits.</li><li><b>Full screen</b> (top right): hides the header and the links. See the note below.</li></ul><div style='border-left:6px solid #22d3ee;background:#083344;padding:10px 14px'><b>Full screen and shared sound.</b> While the tab's sound is shared, Chrome shrinks a page that asks for its own full screen and cuts the sides, and the page cannot detect it. So in that case the button only hides the header and links (the same layout as full screen), and the real full screen is the browser's <code>F11</code>, which works fine. A page also cannot leave F11 full screen by itself.</div><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-perf' style='scroll-margin-top:8px'>Performance and presets</h2><p>Two separate controls, because they answer different questions: <b>presets</b> say <i>how</i> the site reacts, <b>performance</b> says <i>how much</i> the device is asked to do. Performance is remembered per browser and is never touched by presets or by \"reset all\".</p><div style='overflow-x:auto'><table><tr><th>Level</th><th>What changes</th></tr><tr><td><b>Low</b></td><td>No screen glow, no edge bars, no laser streaks</td></tr><tr><td><b>Medium</b> (default)</td><td>Everything the music needs</td></tr><tr><td><b>High</b></td><td>Denser laser streaks; new heavy things should hang on this level too</td></tr><tr><td><b>Rhythm off</b></td><td>Nothing on the site reacts to the beat: no pulses, no effects, no glow</td></tr></table></div><p>The presets are <b>default</b>, <b>calm</b> (weaker effects, fewer flashes, longer waits between lasers), <b>club</b> (stronger and denser) and <b>max</b> (everything much stronger, no flash limit, a new look every 8 beats). The settings page (<code>/settings</code>) shows the few values that make sense for a visitor; it is the same data as the panel on the home page, so a change in one is a change in the other.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-settings' style='scroll-margin-top:8px'>Every setting</h2><p>All 89 numbers the visualizer can be tuned with, grouped like the settings panel. Multipliers use 1 as normal and 0 as off. Click a group to open it.</p>"}, {"type": "embed", "value": "<details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>effects</b> &mdash; how strong each effect is. 1 = normal, 0 = off, no top limit worth worrying about (12)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>kick looks</b></td><td>1</td><td>0 to 50</td><td>multiplies the strength of every kick; below 1 they also fire less often</td></tr><tr><td><b>snare looks</b></td><td>1</td><td>0 to 50</td><td>the same for snares</td></tr><tr><td><b>hat looks</b></td><td>1</td><td>0 to 50</td><td>the same for hi-hats</td></tr><tr><td><b>thin lasers</b></td><td>1</td><td>0 to 50</td><td>the six lasers behind the images and the laser/tick/line looks</td></tr><tr><td><b>thick laser</b></td><td>1</td><td>0 to 50</td><td>the big laser: how wide it gets (0 = never)</td></tr><tr><td><b>laser streaks</b></td><td>1</td><td>0 to 50</td><td>the lines that run along the big laser, away from the logo (0 = none)</td></tr><tr><td><b>drop</b></td><td>1</td><td>0 to 50</td><td>how big the drop reaction is: flash, bursts, grid speed (0 = no reaction)</td></tr><tr><td><b>pixels</b></td><td>1</td><td>0 to 50</td><td>how many pixels stream from the logo and rise from the floor</td></tr><tr><td><b>grid speed</b></td><td>1</td><td>0 to 50</td><td>how much faster the image grid moves when the sound is loud</td></tr><tr><td><b>mood colour</b></td><td>1</td><td>0 to 50</td><td>the faint blue/violet/red glow that follows the mood (0 = off)</td></tr><tr><td><b>logo pulse</b></td><td>1</td><td>0 to 50</td><td>how hard the logo and title hit on every beat</td></tr><tr><td><b>flash power</b></td><td>1</td><td>0 to 5</td><td>how bright the flash looks are (the limit below still applies)</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>whole site</b> &mdash; how the other pages move to the beat: header logo, screen glow, edge pixels and bars. 0 = off (4)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>header logo</b></td><td>1</td><td>0 to 50</td><td>how hard the logo in the header hits on every beat</td></tr><tr><td><b>screen glow</b></td><td>1</td><td>0 to 50</td><td>the faint glow that breathes at the edge of the screen</td></tr><tr><td><b>background flash</b></td><td>1</td><td>0 to 50</td><td>the whole background blinking softly on the beat (0 = off)</td></tr><tr><td><b>edge bars</b></td><td>1</td><td>0 to 50</td><td>the bars on both sides of the screen</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>how often</b> &mdash; how rare or common the big moves are (5)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>thick laser pause</b></td><td>1</td><td>0.05 to 50</td><td>multiplies the wait between big lasers (normally 12 to 26 s)</td></tr><tr><td><b>snare also fires laser</b></td><td>0.6</td><td>0 to 1</td><td>chance that a snare also fires the thin laser</td></tr><tr><td><b>second look</b></td><td>0.3</td><td>0 to 1</td><td>chance of a second look on top of the main one</td></tr><tr><td><b>look changes every</b></td><td>16</td><td>1 to 512</td><td>beats between one set of looks and the next</td></tr><tr><td><b>title swap wait</b></td><td>1</td><td>0 to 50</td><td>multiplies how long the title waits before swapping colours (0 = never)</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>flashes</b> &mdash; the white and bright flashes (also the drop flash) (1)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>max flashes per second</b></td><td>3</td><td>0 to 60</td><td>0 = no limit. 3 is the usual safe limit for people sensitive to flashing</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>where effects show</b> &mdash; turn whole parts of the page on or off (4)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>logo</b></td><td>on</td><td>on / off</td><td>the beat animation of the logo, its rings and size</td></tr><tr><td><b>image wall</b></td><td>on</td><td>on / off</td><td>every look that changes the images</td></tr><tr><td><b>title</b></td><td>on</td><td>on / off</td><td>glitch, blink and colour swap of the title</td></tr><tr><td><b>pixels</b></td><td>on</td><td>on / off</td><td>pixel bursts, sparks and the pixel streams</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>song events</b> &mdash; breaks, build-ups and drops: when they trigger and how they look (21)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>drop sensitivity</b></td><td>1</td><td>0 to 50</td><td>higher = easier to trigger (the jump needed is 0.25 divided by this). 0 = never</td></tr><tr><td><b>drop cooldown (s)</b></td><td>8</td><td>0 to 600</td><td>minimum time between two drops</td></tr><tr><td><b>build-up sensitivity</b></td><td>1</td><td>0 to 50</td><td>higher = a gentler rise counts as a build-up. 0 = never</td></tr><tr><td><b>break sensitivity</b></td><td>1</td><td>0 to 50</td><td>higher = a break is called at a higher volume. 0 = never</td></tr><tr><td><b>break wall opacity</b></td><td>0.4</td><td>0 to 1</td><td>how visible the images stay in a break</td></tr><tr><td><b>open space: shrink</b></td><td>0.5</td><td>0 to 0.5</td><td>how much the wall images shrink (0.5 = half size) in the open space, which comes in a drop: the images get small and far apart. The page itself never changes size. 0 = off</td></tr><tr><td><b>open space: thin out</b></td><td>1</td><td>0 to 1</td><td>how many of the wall images disappear while the open space is on (1 = every other one, so the ones left are twice as far apart; 0 = none)</td></tr><tr><td><b>open space: fill the gaps</b></td><td>0</td><td>0 to 1</td><td>how much a second set of images fills the gaps between the small ones (0 = none, the images stay far apart; 1 = the old, denser look)</td></tr><tr><td><b>open space: bars (at least)</b></td><td>8</td><td>1 to 64</td><td>the open space lasts at least this many bars (4 beats each) after a drop</td></tr><tr><td><b>open space: bars (at most)</b></td><td>16</td><td>1 to 64</td><td>and at most this many: each drop picks a number between the two</td></tr><tr><td><b>open space: image speed</b></td><td>2.5</td><td>1 to 8</td><td>how much faster the images move while it is open (1 = same speed)</td></tr><tr><td><b>open space: in (s)</b></td><td>0.8</td><td>0.2 to 30</td><td>how long the shrink takes (a straight line)</td></tr><tr><td><b>open space: back (s)</b></td><td>3</td><td>0.2 to 60</td><td>how long the return takes (a straight line)</td></tr><tr><td><b>open space: also when very busy</b></td><td>off</td><td>on / off</td><td>also opens it when the big laser stays up for a while (off = only in drops)</td></tr><tr><td><b>busy: wait (s)</b></td><td>2</td><td>0 to 60</td><td>seconds the big laser must stay up before the open space starts (only with the option above)</td></tr><tr><td><b>busy: stay (s)</b></td><td>6</td><td>0 to 120</td><td>seconds without the big laser before it goes back to normal (only with the option above)</td></tr><tr><td><b>open space: hold now</b></td><td>off</td><td>on / off</td><td>keeps the open space on, to see how it looks</td></tr><tr><td><b>drop stars</b></td><td>90</td><td>0 to 1000</td><td>stars streaming past in the space around the page</td></tr><tr><td><b>quiet pulse</b></td><td>0.55</td><td>0 to 1</td><td>how strong the logo pulse stays in very quiet music</td></tr><tr><td><b>logo size (quiet)</b></td><td>0.9</td><td>0.3 to 1</td><td>logo size in quiet music</td></tr><tr><td><b>logo size (loud)</b></td><td>1.12</td><td>1 to 3</td><td>logo size in loud music</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>detection</b> &mdash; what counts as a kick, snare or hat (only when following the tab's sound) (13)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>kick sensitivity</b></td><td>1</td><td>0 to 50</td><td>how little the low end has to rise to count as a kick (0 = off)</td></tr><tr><td><b>snare sensitivity</b></td><td>1</td><td>0 to 50</td><td>the same for snares</td></tr><tr><td><b>hat sensitivity</b></td><td>1</td><td>0 to 50</td><td>the same for hats</td></tr><tr><td><b>kick floor</b></td><td>0.35</td><td>0.01 to 20</td><td>smallest rise that can ever be a kick (keeps hiss from counting)</td></tr><tr><td><b>snare floor</b></td><td>0.9</td><td>0.01 to 20</td><td>smallest rise that can ever be a snare</td></tr><tr><td><b>hat floor</b></td><td>0.5</td><td>0.01 to 20</td><td>smallest rise that can ever be a hat</td></tr><tr><td><b>kick range ends at (Hz)</b></td><td>160</td><td>60 to 400</td><td>the low band, where kicks live, ends here. Raise for a boomy kick, lower for a tight one</td></tr><tr><td><b>hat range starts at (Hz)</b></td><td>5000</td><td>2000 to 12000</td><td>the air band, where hats live, starts here</td></tr><tr><td><b>hat: air over the rest</b></td><td>1.5</td><td>0 to 20</td><td>a hat needs this much more air and snap than low, body and mid</td></tr><tr><td><b>kick: low over body</b></td><td>0.7</td><td>0 to 20</td><td>a kick needs at least this much low end compared with the body range</td></tr><tr><td><b>snare: snap over low</b></td><td>0.25</td><td>0 to 20</td><td>a snare needs at least this much snap compared with the low end</td></tr><tr><td><b>kick/snare gap (ms)</b></td><td>70</td><td>10 to 500</td><td>after a kick or snare, wait this long before hearing another</td></tr><tr><td><b>hat gap (ms)</b></td><td>40</td><td>10 to 500</td><td>the same for hats</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>decisions</b> &mdash; what the groove does with the hits it heard: grid, ghosts, patterns (18)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>grid tolerance</b></td><td>0.3</td><td>0.05 to 0.5</td><td>how far (in 16th steps) a hit can sit from the grid and still be snapped to it</td></tr><tr><td><b>strong hit</b></td><td>1.6</td><td>0.3 to 10</td><td>a hit this strong is shown as heard even when it is off the grid</td></tr><tr><td><b>weak hit</b></td><td>1.3</td><td>0.1 to 10</td><td>only hits weaker than this can be dropped for not fitting the pattern</td></tr><tr><td><b>same-sound gap</b></td><td>0.65</td><td>0.1 to 2</td><td>steps: a hit this soon after the last one of its kind is the same sound heard again</td></tr><tr><td><b>ghost eagerness</b></td><td>0.7</td><td>0.05 to 1</td><td>a step is filled in when its memory is at least this. Lower = more ghosts</td></tr><tr><td><b>floor ghost eagerness</b></td><td>0.45</td><td>0.05 to 1</td><td>the same, for the kick on a beat while four on the floor is likely</td></tr><tr><td><b>ghosts in a row</b></td><td>2</td><td>0 to 16</td><td>how many ghosts in a row one step gets before it is let go</td></tr><tr><td><b>weak-hit gate</b></td><td>0.2</td><td>0 to 1</td><td>a weak hit on a step with less memory than this is dropped</td></tr><tr><td><b>bars to lock a pattern</b></td><td>2</td><td>1 to 16</td><td>how many bars in a row must fit before the pattern is locked</td></tr><tr><td><b>bars to let it go</b></td><td>2</td><td>1 to 16</td><td>how many bars in a row must not fit before the pattern is dropped</td></tr><tr><td><b>pattern switch margin</b></td><td>0.25</td><td>0 to 1</td><td>another pattern must fit this much better to take over</td></tr><tr><td><b>lock the genre pattern</b></td><td>on</td><td>on / off</td><td>recognise and lock the kick pattern</td></tr><tr><td><b>four on the floor assist</b></td><td>on</td><td>on / off</td><td>easier four on the floor, and the forced mode below</td></tr><tr><td><b>swing (%)</b></td><td>50</td><td>50 to 75</td><td>50 = straight 16ths, 66.7 = triplet feel (shuffle, trap, hip hop)</td></tr><tr><td><b>follow the grid by ear</b></td><td>on</td><td>on / off</td><td>the grid follows where kicks and snares really land</td></tr><tr><td><b>grid offset</b></td><td>0</td><td>-0.5 to 0.5</td><td>steps, used when the line above is off</td></tr><tr><td><b>grid follow speed</b></td><td>0.2</td><td>0 to 1</td><td>how fast the grid follows the hits</td></tr><tr><td><b>detection delay (ms)</b></td><td>27</td><td>0 to 200</td><td>how long after a hit starts the detector reports it</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>forced four on the floor</b> &mdash; when it gives up on the hits and puts a kick on every beat (7)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>loud above</b></td><td>0.45</td><td>0 to 1</td><td>only when the sound is at least this loud</td></tr><tr><td><b>rejected vs passed</b></td><td>1.5</td><td>0 to 20</td><td>hits thrown away this many times more than passed counts as messy</td></tr><tr><td><b>tempo changes</b></td><td>2</td><td>1 to 20</td><td>this many BPM changes in 10 s count as messy</td></tr><tr><td><b>kick gone after (beats)</b></td><td>6</td><td>1 to 64</td><td>no kick for this long after a kick pattern counts as messy</td></tr><tr><td><b>switch on after (s)</b></td><td>2</td><td>0 to 60</td><td>messy for this long turns it on</td></tr><tr><td><b>switch off after (s)</b></td><td>4</td><td>0 to 60</td><td>clear for this long turns it off</td></tr><tr><td><b>sound threshold</b></td><td>0.1</td><td>0 to 1</td><td>below this loudness there is no sound (no ghosts in silence)</td></tr></table></div></details><details style='margin:8px 0;border:1px solid #164e63;padding:8px 12px'><summary style='cursor:pointer'><b>tempo</b> &mdash; how the BPM is guessed (4)</summary><div style='overflow-x:auto'><table><tr><th>Setting</th><th>Default</th><th>Range</th><th>What it does</th></tr><tr><td><b>lowest BPM</b></td><td>70</td><td>30 to 300</td><td>the slowest tempo it will pick</td></tr><tr><td><b>highest BPM</b></td><td>190</td><td>60 to 400</td><td>the fastest tempo it will pick</td></tr><tr><td><b>prefer faster</b></td><td>0.6</td><td>0 to 1</td><td>when half or double of a tempo both fit, how much to favour the faster one</td></tr><tr><td><b>usual BPM</b></td><td>120</td><td>60 to 200</td><td>the tempo it expects first</td></tr></table></div></details>"}, {"type": "text", "value": "<p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-music' style='scroll-margin-top:8px'>Music player and /music</h2><p>The player lives on every page and stays mounted for the whole visit, so the music keeps going when the visitor changes page. It is only faded and slid out of view, never hidden with <code>display:none</code> (the YouTube player needs at least 200 by 200 pixels).</p><h3>What can be played</h3><ul><li><b>A song name:</b> searched on YouTube (YouTube Data API; results are cached in the browser).</li><li><b>A YouTube link</b>, including playlists.</li><li><b>A SoundCloud link</b>, short links included (a short link is resolved through SoundCloud's oEmbed first).</li><li><b>A Spotify link:</b> Spotify only gives the title, so the title is read and searched on YouTube.</li><li><b>A direct audio file</b> (mp3, wav, ogg, m4a, flac and others): the files uploaded on the music page live in the site's own storage.</li><li><b>Play with nothing typed:</b> one of the songs saved on the music page, at random, none twice until all have played.</li></ul><h3>When the queue ends</h3><p>The site looks for a similar song so the music does not stop: first Last.fm's similar tracks (the song is found on YouTube afterwards, since Last.fm only gives names); when Last.fm does not know the song (typical for my own music or SoundCloud titles), YouTube is searched with the song's own title and the first result that is not that song plays.</p><h3>The /music page</h3><p>A list of my tracks: title, play, BPM, a note and an optional picture. Playing one sends it to the same player as the home page, so the whole site follows its beat. Only the admin sees the form to add tracks. It accepts a link or a file from the computer (uploaded to the <code>music</code> bucket), and a picture for the track (a <code>thumbs</code> folder in the same bucket, png, jpg, gif, webp or avif). Tracks can also be edited (replaced files are removed from storage) and deleted.</p><h3>On phones</h3><p>A browser may block a song from starting by itself, SoundCloud above all. If nothing plays a few seconds after a song was asked for, the player opens and says what to do.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-accounts' style='scroll-margin-top:8px'>Accounts and profiles</h2><p>Anyone can create an account from the header. An account has a <b>unique nickname</b>, an optional <b>profile picture</b> and a <b>nickname colour</b> (chosen with a picker, saved a moment after the last change), which is how the name looks in the chat and the mural. Without a chosen colour one is made from the account id, so it stays the same. Accounts are also what lets a visitor track their own skills.</p><p>The owner's account carries an <b>admin flag</b> (<code>app_metadata.is_admin</code>). It is what shows the editors of the blog, projects, music and gallery, and the delete buttons of the chat and the mural. The buttons are only a convenience: the database itself refuses those actions for anyone else (see <a href='#doc-backend'>Backend and storage</a>).</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-chat' style='scroll-margin-top:8px'>Live chat</h2><p>On the home page, a transparent chat on the right. It is a short-lived talk, not a record:</p><ul><li>Messages up to 140 characters, <b>one message every 10 seconds</b>.</li><li>New messages appear live. The page keeps the last 50 and the screen shows the last few.</li><li>Visitors without an account write as anonymous sessions: a nickname they pick and a random colour kept in their browser. Anonymous visitors use their <b>own database client with its own session storage</b>, so they never look \"logged in\" to the header, blog, gallery or projects.</li><li>With an account, the message goes out under the account's nickname and colour with nothing to ask.</li><li>It can be collapsed, and it steps aside when the data panel or the pad is open. The admin can delete any message with a small x at the start of the line.</li></ul><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-mural' style='scroll-margin-top:8px'>Mural</h2><p>The guestbook, at <code>/mural</code>. Unlike the chat, it keeps what is written. A message up to 400 characters with a nickname (visitors) or the account's nickname and colour. It is not linked from the menus on purpose: the address is given to whoever should leave a message. The admin can delete entries (two clicks, \"sure?\").</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-skills' style='scroll-margin-top:8px'>Skill tracker</h2><p>At <code>/self-improvement</code>, a tool to follow progress in public. Every signed-in visitor can track their own skills; mine is the one on the page of my nickname.</p><ul><li>A <b>skill</b> has a name, a description, an icon, a self-rating from 0 to 100 in steps of 5 (drawn as ten pixel blocks) and two pictures: where I am and where I want to be.</li><li>Each skill can have <b>traits</b>, small parts of the skill that are rated on their own (for example, perspective inside pixel art).</li><li>Each skill is <b>public or private</b>. Public skills can be seen by anyone at <code>/self-improvement/&lt;nickname&gt;</code>; private ones only by the owner.</li><li>The search box at the top right finds other people by nickname.</li><li>The bars never signal a \"bad\" level: someone just starting should not feel punished.</li></ul><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-content' style='scroll-margin-top:8px'>Projects, blog and gallery</h2><p>The three content pages share the same idea: an admin editor builds the page out of <b>blocks</b>.</p><div style='overflow-x:auto'><table><tr><th>Block</th><th>Holds</th></tr><tr><td>text</td><td>HTML (headings, lists, tables, links)</td></tr><tr><td>embed</td><td>Any HTML, for layouts like rows of text beside pictures, or an iframe (YouTube, maps...)</td></tr><tr><td>image / video / audio</td><td>A link; files chosen in the editor are uploaded to storage</td></tr></table></div><ul><li><b>Projects</b> (<code>/projects</code>): a cover (the first image, or a big letter), a status (planning, in progress, paused, completed or suspended), a short description and a last-update date. This page is a project: sections are built with embed blocks and anchors (<code>id</code> plus a <code>#link</code>), which is what makes the contents above work.</li><li><b>Blog</b> (<code>/blog</code>): posts with an icon, an optional thumbnail, a name, a title, a summary and blocks. The embed editor can upload a picture and insert it in the code by itself.</li><li><b>Gallery</b> (<code>/gallery</code>): three folders &mdash; pixel arts, edits (videos and visuals) and dance. A masonry wall that keeps each piece at its own shape, with the name and description over a dark fade at the bottom. A piece opens in a viewer with the keys <code>&larr;</code>, <code>&rarr;</code> and <code>Esc</code>.</li></ul><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-backend' style='scroll-margin-top:8px'>Backend and storage</h2><p>The backend is <b>Supabase</b>: Postgres tables with row level security, authentication and file buckets. The project address and the public key in the page are public by design; what protects the data is the security rules in the database, not hiding the key.</p><div style='overflow-x:auto'><table><tr><th>Table</th><th>Used for</th></tr><tr><td>profiles</td><td>Nickname (unique, case-insensitive), nickname colour, profile picture</td></tr><tr><td>chat_messages</td><td>The live chat</td></tr><tr><td>guestbook</td><td>The mural</td></tr><tr><td>tracks</td><td>The music page</td></tr><tr><td>blog_posts</td><td>The blog</td></tr><tr><td>projects</td><td>The projects, including this page</td></tr><tr><td>skills, traits</td><td>The skill tracker</td></tr><tr><td>gallery</td><td>The pieces of the gallery</td></tr></table></div><div style='overflow-x:auto'><table><tr><th>Bucket</th><th>Holds</th></tr><tr><td>music</td><td>Uploaded songs and track pictures (restricted types: audio and images, gif included)</td></tr><tr><td>gallery</td><td>Gallery pieces</td></tr><tr><td>blog_media</td><td>Pictures, video and audio of blog posts, in a folder per post</td></tr><tr><td>skills</td><td>Skill icons and pictures</td></tr><tr><td>profile_pictures</td><td>Profile pictures</td></tr></table></div><p><b>Rules.</b> Anyone can read the public content. Writing in the chat and the mural needs a session (an account, or the anonymous session a visitor gets when writing). Deleting chat and mural messages, and editing the blog, projects, music and gallery, needs the admin flag (<code>app_metadata.is_admin</code>): the buttons only show for the admin, and the database refuses those actions for anyone else. Skills marked private are shown only to their owner. The YouTube and Last.fm keys live in the <code>.env</code> file (the YouTube one is restricted by referrer in Google Cloud).</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-limits' style='scroll-margin-top:8px'>Known limits</h2><ul><li><b>Phones cannot hear the page.</b> Browsers on phones cannot share a tab's sound, so there the bars and effects follow a pretend pattern from the tempo, tapped or default.</li><li><b>Only desktop Chromium follows the real sound</b> (Chrome, Edge). Other desktop browsers use the tempo-only mode.</li><li><b>Detection is an estimate.</b> It works best on clear drum patterns; very dense, quiet or syncopated music can fool it. The groove and the forced mode exist to keep the show in time anyway.</li><li><b>Tab sharing and full screen.</b> While the tab's sound is shared, the page's own full screen button only hides the header; use <code>F11</code> for the real one.</li><li><b>Lag mode is a test.</b> It is not remembered between visits.</li><li><b>Cost.</b> The effects use a lot of animation. If a device struggles, set performance to low or turn the rhythm off.</li><li><b>Tuning is never finished.</b> The detection can always be improved with more real music.</li></ul><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-controls' style='scroll-margin-top:8px'>Keys, links and URL tricks</h2><h3>Keys</h3><div style='overflow-x:auto'><table><tr><th>Key</th><th>Does</th></tr><tr><td><code>T</code></td><td>Tap the beat</td></tr><tr><td><code>[</code> and <code>]</code></td><td>Move the pulse 10 ms earlier or later</td></tr><tr><td><code>F11</code></td><td>The browser's full screen (works while the tab's sound is shared)</td></tr><tr><td><code>Esc</code></td><td>Closes the sidebar, the account menu and the gallery viewer</td></tr><tr><td><code>&larr;</code> <code>&rarr;</code></td><td>Previous and next piece in the gallery viewer</td></tr><tr><td><code>Enter</code></td><td>Applies a typed BPM or a typed setting</td></tr></table></div><h3>URL tricks (for trying things)</h3><div style='overflow-x:auto'><table><tr><th>Add to the address</th><th>Does</th></tr><tr><td><code>?kick=checker</code></td><td>Forces one kick look (checker, shove, flash, lines, slide, lanes)</td></tr><tr><td><code>?snare=laser</code></td><td>Forces one snare look (laser, columns, glitch, hue, pixels)</td></tr><tr><td><code>?hat=twinkle</code></td><td>Forces one hat look (twinkle, sparks, tick, blink)</td></tr><tr><td><code>?bg=step</code></td><td>The wall moves in steps on the beat instead of drifting</td></tr><tr><td><code>?bands=manual</code></td><td>Loudness set by hand, to try effects without music</td></tr></table></div><h3>Links inside this page</h3><p>Every section has an address of its own: add <code>#doc-clock</code>, <code>#doc-groove</code> and so on to the page address to send someone straight to a section.</p><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}, {"type": "text", "value": "<h2 id='doc-glossary' style='scroll-margin-top:8px'>Glossary</h2><div style='overflow-x:auto'><table><tr><th>Word</th><th>Meaning</th></tr><tr><td>BPM</td><td>Beats per minute: the tempo</td></tr><tr><td>Beat</td><td>One tick of the tempo; 4 beats make a bar</td></tr><tr><td>Bar</td><td>4 beats, 16 sixteenth-note steps</td></tr><tr><td>Step</td><td>A sixteenth note: a quarter of a beat. The grid hits are snapped to</td></tr><tr><td>Kick, snare, hat</td><td>The three drums the site tells apart: the low thump, the snap on 2 and 4, and the high tick</td></tr><tr><td>Band</td><td>One of the 24 slices of the spectrum, from 40 Hz to 10 kHz</td></tr><tr><td>Group</td><td>One of five parts of the spectrum: low, body, mid, crack, air</td></tr><tr><td>Onset</td><td>The moment new sound starts</td></tr><tr><td>Spectral flux</td><td>How much the spectrum grew since the last reading; the signal the tempo is found in</td></tr><tr><td>Anchor</td><td>The moment one beat started, from which every other beat is counted</td></tr><tr><td>Ghost</td><td>A hit filled in from a known pattern, not heard</td></tr><tr><td>Look</td><td>One visual effect that reacts to a kind of hit</td></tr><tr><td>Break</td><td>A quiet moment after loud music</td></tr><tr><td>Build-up</td><td>A steady rise before a drop</td></tr><tr><td>Drop</td><td>The moment the music comes back loud and big</td></tr><tr><td>Open space</td><td>The mode where the wall images shrink and spread apart after a drop</td></tr><tr><td>Preset</td><td>A saved set of settings: default, calm, club, max</td></tr></table></div><p style='text-align:right;font-size:12px;margin:0'><a href='#doc-contents'>&uarr; contents</a></p>"}]$j$::jsonb,
    now(),
    now()
);
